INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24201, 'Luke 9:27', 'Luke', 9, 27, '&nbsp;خو زۀ تاسو ته رښتيا وايم چې دلته ځينې داسې کسان ولاړ دى چې هغوئ به تر هغې نۀ مرى ترڅو چې د خُدائ پاک بادشاهى ونۀ وينى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24202, 'Luke 9:28', 'Luke', 9, 28, '&nbsp;د دې خبرو نه اتۀ ورځې پس هغۀ پطروس، يوحنا او يعقوب د ځان سره کړل او د دُعا دپاره غرۀ ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24203, 'Luke 9:29', 'Luke', 9, 29, '&nbsp;هر کله چې هغۀ دُعا کوله نو د هغۀ شکل بدل شو او د هغۀ جامې برېښېدونکې سپينې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24204, 'Luke 9:30', 'Luke', 9, 30, '&nbsp;نو ناګهانه هغوئ دوه سړى وليدل چې موسىٰ او الياس وُو، چې د هغۀ سره يې خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24205, 'Luke 9:31', 'Luke', 9, 31, '&nbsp;هغوئ په جلال کښې ښکاره شول او د هغۀ د مرګ په حقله يې خبرې وکړې چې په يروشلم کښې پوره کېدونکې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24206, 'Luke 9:32', 'Luke', 9, 32, '&nbsp;په دې وخت کښې پطروس او د هغۀ ملګرى په ښۀ خوب ورغلى وُو، خو هر کله چې هغوئ بېدار شول نو هغوئ د دۀ جلال وليدو او هغه دوه سړى يې هم ورسره ولاړ وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24207, 'Luke 9:33', 'Luke', 9, 33, '&nbsp;او کله چې هغوئ د عيسىٰ نه رخصتېدل نو پطروس عيسىٰ ته ووئيل چې، ”مالِکه، زمونږ دپاره دلته پاتې کېدل ښۀ دى. مونږ پرېږده چې درې جونګړې جوړې کړُو، يوه ستا دپاره، يوه د موسىٰ دپاره او يوه د الياس دپاره.“ خو هغه نۀ پوهېدو چې څۀ يې وئيل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24208, 'Luke 9:34', 'Luke', 9, 34, '&nbsp;هغۀ لا دا خبرې کولې چې يوه وريځ راخوره شوه او په هغوئ يې سورے وکړو. هغوئ ويرېدل څنګه چې په وريځ کښې ننوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24209, 'Luke 9:35', 'Luke', 9, 35, '&nbsp;بيا د وريځې نه يو آواز راغلو چې وې فرمائيل، ”دا زما زوئ دے، زما غوره کړے. د دۀ خبرې واورئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24210, 'Luke 9:36', 'Luke', 9, 36, '&nbsp;هر کله چې آواز ختم شو نو عيسىٰ يې يواځې وليدلو. نو مريدان غلى پاتې شول او هر څۀ چې يې ليدلى وُو، په هغه وخت يې هيچا ته هم حال ونۀ وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24211, 'Luke 9:37', 'Luke', 9, 37, '&nbsp;بله ورځ چې هغوئ د غرۀ نه راکوز شول نو ډېره لويه ګڼه ورته راټوله شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24212, 'Luke 9:38', 'Luke', 9, 38, '&nbsp;بيا د ګڼې نه يو سړى چغه کړه، ”اُستاذه، زارى درته کوم چې زما په يک يو زوئ نظر وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24213, 'Luke 9:39', 'Luke', 9, 39, '&nbsp;هر وخت يې پيرے نيسى، چغې ترې وباسى، تاو راتاو يې کړى او را وى غورزوى او په خوله يې ځګونه رامات شى او چې ډېر بد يې زخمى کړى نو هله ترې لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24214, 'Luke 9:40', 'Luke', 9, 40, '&nbsp;ما ستا مريدانو ته خواست وکړو چې دا ترې نه وباسئ خو هغوئ پاتې راغلل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24215, 'Luke 9:41', 'Luke', 9, 41, '&nbsp;عيسىٰ جواب ورکړو، ”اے بې‌ايمانه او بدکاره پيړۍ. زۀ به ترڅو تاسو سره يم او تاسو به زغمم؟ خپل زوئ دلته راوله.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24216, 'Luke 9:42', 'Luke', 9, 42, '&nbsp;خو د راوستو نه مخکښې پيريانو هغه ماشوم راوپرزولو او تاو راتاو يې کړو، خو عيسىٰ پيرے ورټلو، هلک يې روغ کړو او پلار ته يې واپس حواله کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24217, 'Luke 9:43', 'Luke', 9, 43, '&nbsp;او هغوئ ټول د خُدائ پاک د لويئ او د هغۀ د شان او شوکت يرې واخستل. د حضرت عيسىٰ د خپل مرګ په حقله بيا پېشګوئې ټول خلق د دۀ په دې ټولو کارونو حېران شول او عيسىٰ په دې وخت کښې خپلو مريدانو ته وفرمائيل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24218, 'Luke 9:44', 'Luke', 9, 44, '&nbsp;”پرېږدئ او دا خبرې په کولاو غوږونو واورئ. اِبن آدم به د دشمنانو لاسونو ته حواله کړے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24219, 'Luke 9:45', 'Luke', 9, 45, '&nbsp;خو هغوئ د هغۀ په دې وينا پوهه نۀ شول ځکه چې د دې مطلب د هغوئ نه پټ وو د دې دپاره چې هغوئ په دې ونۀ رسى او هغوئ په دې حقله د هغۀ نه د تپوس کولو نه هم يرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24220, 'Luke 9:46', 'Luke', 9, 46, '&nbsp;د هغوئ په مينځ کښې دا بحث شروع شو چې په مونږ کښې د ټولو نه لوئ څوک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24221, 'Luke 9:47', 'Luke', 9, 47, '&nbsp;عيسىٰ په دې پوهه وو چې د دوئ په زړُونو کښې څۀ تېريږى نو هغۀ يو ماشوم د لاسه ونيولو او په خپله خوا کښې يې ودرولو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24222, 'Luke 9:48', 'Luke', 9, 48, '&nbsp;او هغوئ ته يې وفرمائيل، ”څوک چې زما په نوم داسې ماشوم قبول کړى هغه ما قبلوى، او څوک چې ما قبلوى هغه، هغه څوک قبلوى چې زۀ يې رالېږلے يم. ځکه چې په تاسو ټولو کښې ورکوټے په تاسو ټولو کښې لوئ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24223, 'Luke 9:49', 'Luke', 9, 49, '&nbsp;يوحنا ووئيل، ”مالِکه، مونږ يو سړے وليدو چې ستا په نوم پيريان شړى، او مونږ د هغۀ د منع کولو کوشش وکړو ځکه هغه زمونږ نه نۀ وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24224, 'Luke 9:50', 'Luke', 9, 50, '&nbsp;خو عيسىٰ هغۀ ته وفرمائيل، ”هغه مۀ منع کوئ ځکه چې څوک ستاسو مخالف نۀ دے، هغه ستاسو ملګرے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24225, 'Luke 9:51', 'Luke', 9, 51, '&nbsp;هر کله چې هغه وخت رانزدې شو چې عيسىٰ پاس آسمان ته وخېژولے شى نو هغۀ يروشلم ته د تلو پوخ نيت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24226, 'Luke 9:52', 'Luke', 9, 52, '&nbsp;او هغۀ د ځان نه وړاندې پېغام وړُونکى ولېږل. هغوئ لاړل او د سامريه يو کلى ته ورغلل چې د هغۀ دپاره د ځائ تيارى وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24227, 'Luke 9:53', 'Luke', 9, 53, '&nbsp;خو د کلى خلقو هغه قبول نۀ کړو ځکه چې هغۀ مخه د يروشلم په لور تړلې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24228, 'Luke 9:54', 'Luke', 9, 54, '&nbsp;هر کله چې د هغۀ مريدانو يعقوب او يوحنا دا حال وليدلو نو وې وئيل، ”مالِکه، مونږ د آسمان نه د دې کلى د سوزولو دپاره اور وغواړو څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24229, 'Luke 9:55', 'Luke', 9, 55, '&nbsp;خو هغۀ ورته مخ ورواړوو او وې رټل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24230, 'Luke 9:56', 'Luke', 9, 56, '&nbsp;نو بيا هغوئ بل کلى ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24231, 'Luke 9:57', 'Luke', 9, 57, '&nbsp;کله چې هغوئ په لاره روان وُو نو يو سړى هغۀ ته ووئيل، ”هر چرته چې تۀ ځې، زۀ به هم درپسې ځم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24232, 'Luke 9:58', 'Luke', 9, 58, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”د لومبړو خپل غارونه وى او د مارغانو جالې، خو اِبن آدم دومره ځائ قدرې هم نۀ لرى چې سر په کښې ولګوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24233, 'Luke 9:59', 'Luke', 9, 59, '&nbsp;بل چا ته هغۀ وفرمائيل چې، ”په ما پسې راځه.“ خو سړى جواب ورکړو، ”مالِکه، اول ما ته اجازت راکړه چې خپل پلار ښخ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24234, 'Luke 9:60', 'Luke', 9, 60, '&nbsp;خو عيسىٰ ورته وفرمائيل، ”مړى پرېږدئ چې مړى ښخوى خو تۀ خامخا لاړ شه او د خُدائ پاک د بادشاهۍ زيرے ورکوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24235, 'Luke 9:61', 'Luke', 9, 61, '&nbsp;او بيا يو بل ووئيل، ”مالِکه، زۀ به درپسې يم خو دومره اجازت راکړه چې د خپل کور د خلقو نه رُخصت واخلم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24236, 'Luke 9:62', 'Luke', 9, 62, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”کوم سړے چې قُلبه کول شروع کړى بيا شاته ګورى هغه د خُدائ پاک د بادشاهۍ لائق نۀ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24237, 'Luke 10:1', 'Luke', 10, 1, '&nbsp;د دې نه پس بيا مالِک نور دوه اويا کسان مقرر کړل او هغوئ يې دوه دوه کسان هر ښار او کلى ته د ځان نه وړاندې ولېږل، کومو ته چې د هغۀ د ورتلو اراده وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24238, 'Luke 10:2', 'Luke', 10, 2, '&nbsp;هغۀ هغوئ ته وفرمائيل، ”فصل ډېر دے خو مزدوران لږ دى. د دې دپاره تاسو د فصل مالِک ته خواست وکړئ چې د خپل فصل دپاره مزدوران راولېږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24239, 'Luke 10:3', 'Luke', 10, 3, '&nbsp;په خپله لاره ځئ او ګورئ، زۀ تاسو لکه د ګډو په شان د شرمخانو مينځ ته لېږم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24240, 'Luke 10:4', 'Luke', 10, 4, '&nbsp;د ځان سره بټوه مۀ اخلئ، نۀ تيلۍ او نۀ پېزار. او په لاره د چا سره په دُعا سلام ډېر وخت مۀ ضائع کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24241, 'Luke 10:5', 'Luke', 10, 5, '&nbsp;هر کله چې تاسو يو کور ته ننوځئ نو اول دا ووايئ، په دې کور کښې دې خير او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24242, 'Luke 10:6', 'Luke', 10, 6, '&nbsp;کۀ چرې هلته يو کس خير خواه وى نو ستاسو سلامتى به د هغۀ دپاره وى، او کۀ نۀ وى نو هغه به تاسو ته راواپس شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24243, 'Luke 10:7', 'Luke', 10, 7, '&nbsp;هم هغه کور کښې پاتې شئ او د هغوئ سره خوړل څښل وکړئ او ست مۀ غواړئ ځکه چې مزدور د مزدورۍ حقدار وى. کور په کور مۀ ګرځئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24244, 'Luke 10:8', 'Luke', 10, 8, '&nbsp;هر کله چې تاسو يوې ښاريې ته ورننوځئ او هغوئ تاسو ته هرکلے ووائى نو کوم خوراک چې تاسو ته درکړى، هغه وخورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24245, 'Luke 10:9', 'Luke', 10, 9, '&nbsp;هلته بيماران روغ کړئ او هغوئ ته ووايئ چې د خُدائ پاک بادشاهى ستاسو مينځ ته راغلې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24246, 'Luke 10:10', 'Luke', 10, 10, '&nbsp;خو چې تاسو يو ښار ته ننوځئ او هغوئ تاسو قبول نۀ کړى نو د دې کوڅو ته بهر ووځئ او ووايئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24247, 'Luke 10:11', 'Luke', 10, 11, '&nbsp;ستاسو د ښاريې دا کومه دوړه چې زمونږ په پښو پورې انښتې ده، مونږ يې ستاسو خلاف څنډو. خو دا خبره ياده لرئ چې د خُدائ پاک بادشاهى ستاسو مينځ ته راغلې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24248, 'Luke 10:12', 'Luke', 10, 12, '&nbsp;زۀ تاسو ته دا وايم چې د قيامت په ورځ به د سدوم حال د دغه ښار نه زيات د زغملو وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24249, 'Luke 10:13', 'Luke', 10, 13, '&nbsp;افسوس دې وى په تا اے خورازينه، افسوس دې وى په تا بيتِ‌صيدا، ځکه کومې معجزې چې په تا کښې وشوې کۀ چرې دا په صور او صيدا کښې شوې وې نو دوئ به ډېر پخوا د ځان نه د ټاټ جامې تاو کړې وې او په ايرو کښې به ناست وُو او توبه به يې ويستې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24250, 'Luke 10:14', 'Luke', 10, 14, '&nbsp;خو د قيامت په ورځ به د صور او صيدا حالت ستاسو نه ډېر غوره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24251, 'Luke 10:15', 'Luke', 10, 15, '&nbsp;او اے کفرنحُومه، ولې تۀ دا ګڼې چې ستا مقام به تر آسمانه پورته کړے شى څۀ؟ نه، تۀ به تاترين ته وغورزولے شې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24252, 'Luke 10:16', 'Luke', 10, 16, '&nbsp;هر څوک چې ستاسو خبرې ته غوږ نيسى، هغه ما ته غوږ نيسى او هر څوک چې ستاسو خبره رد کوى، هغه ما رد کوى او څوک چې ما رد کوى، هغه هم هغه رد کوى چې زۀ يې رالېږلے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24253, 'Luke 10:17', 'Luke', 10, 17, '&nbsp;بيا هغه دوه اويا کسان خوشحاله واپس راغلل او وې وئيل چې، ”اے مالِکه، ستا په نوم پيريان هم زمونږ تابعدارى کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24254, 'Luke 10:18', 'Luke', 10, 18, '&nbsp;هغۀ جواب ورکړو، ”ما دا وليدل چې شېطان لکه د برېښنا په شان د آسمان نه راکوز شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24255, 'Luke 10:19', 'Luke', 10, 19, '&nbsp;ګورئ، ما تاسو له اختيار درکړو چې ماران او لړمان د پښو لاندې کړئ او د دشمن طاقت هم ختموئ او هيڅ څيز به هم تاسو ته نقصان نۀ شى درکولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24256, 'Luke 10:20', 'Luke', 10, 20, '&nbsp;خو په دې مۀ خوشحالېږئ چې پيريان ستاسو تابعدارى کوى بلکې په دې خوشحاله شئ چې ستاسو نومونه په آسمان کښې وليکلے شول.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24257, 'Luke 10:21', 'Luke', 10, 21, '&nbsp;هم په دغه وخت عيسىٰ په روحُ القُدس کښې لويه خوشحالى وکړه او عيسىٰ وفرمائيل، ”اے پلاره، د آسمان او د زمکې مالِکه، زۀ ستا ثنا او صِفت کوم ځکه چې تا دا خبرې د پوهانو او هوښيارو نه پټې کړې او وړو ماشومانو ته دې څرګندې کړې. آو، پلاره، دا ستا رضا وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24258, 'Luke 10:22', 'Luke', 10, 22, '&nbsp;هر څۀ ما ته زما پلار سپارلى دى، او هيڅوک بې د پلاره زوئ نۀ پېژنى، او نۀ څوک پلار پېژنى بې له زويه او بې له هغوئ نه چې زوئ يې ورته په ګوته کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24259, 'Luke 10:23', 'Luke', 10, 23, '&nbsp;بيا هغه خپلو مريدانو ته راوګرځېدو او ځان له يې ورته وفرمائيل، ”هغه سترګې بختورې دى چې هغه څۀ وينى چې تاسو يې وينئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24260, 'Luke 10:24', 'Luke', 10, 24, '&nbsp;زۀ تاسو ته وايم چې د ډېرو نبيانو او بادشاهانو دا ارمان وُو چې هغه څۀ ووينى څۀ چې تاسو وينئ خو هغوئ ونۀ ليدل او هغه څۀ واورى چې تاسو يې اوس اورئ خو هغوئ وانۀ ورېدل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24261, 'Luke 10:25', 'Luke', 10, 25, '&nbsp;په يوه موقع يو د شرعې عالم راغلو او په عيسىٰ يې د آزمېښت دپاره دا سوال وکړو، ”اُستاذه، زۀ داسې څۀ وکړم چې د ابدى ژوندون وارث شم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24262, 'Luke 10:26', 'Luke', 10, 26, '&nbsp;عيسىٰ ورته وفرمائيل، ”په شريعت کښې يې څۀ ليکلى دى؟ تۀ يې څنګه لولې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
